import csv,json,math
with open('input.csv',newline='') as f: rows=list(csv.reader(f))
def num(s):
 try: float(s); return True
 except ValueError: return False
def fmt(x): return format(x,'.15g')
for i in range(1,len(rows)):
 if rows[i][1]!='': continue
 lo=next((j for j in range(i-1,0,-1) if num(rows[j][1])),None)
 hi=next((j for j in range(i+1,len(rows)) if num(rows[j][1])),None)
 if lo is not None and hi is not None:
  rows[i][1]=fmt(float(rows[lo][1])+(float(rows[hi][1])-float(rows[lo][1]))*(i-lo)/(hi-lo))
print(json.dumps({'exit':0,'csv':'\n'.join(','.join(r) for r in rows)+'\n'}))

