import csv,json
with open('left.csv',newline='') as f:l=list(csv.DictReader(f))
with open('right.csv',newline='') as f:r=list(csv.DictReader(f))
first={}
for x in r:first.setdefault(x['id'],x)
out=[]
for x in l:
 y=first.get(x['id'],{})
 out.append((x['id'],y.get('y','')))
print(json.dumps({'a5':out[0][0],'a5b':out[0][1],'a5c':out[1][1]}))
